#!/usr/bin/env node
/**
 * R335 P0-7 — per-module attribution for Metro "sections" source maps.
 * `expo export -s external` emits one index map per chunk ({ version,
 * sections: [...] }); scripts/analyze-bundle.mjs only reads plain maps, so
 * this flattens every section (each section's own VLQ mappings decoded with
 * the same algorithm) into per-source generated bytes, plus a package-level
 * rollup. Usage:
 *   npx expo export --platform web -s external --output-dir dist
 *   node scripts/analyze-sections.mjs dist/_expo/static/js/web/__common-*.map [--top 25]
 */
import fs from "node:fs";

function decodeVLQ(str) {
  const chars = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
  const out = [];
  let shift = 0;
  let value = 0;
  for (const c of str) {
    const d = chars.indexOf(c);
    if (d < 0) continue;
    value += (d & 31) << shift;
    if (d & 32) {
      shift += 5;
    } else {
      const neg = value & 1;
      value >>= 1;
      out.push(neg ? -value : value);
      value = 0;
      shift = 0;
    }
  }
  return out;
}

function attribute(m, perSource, sources) {
  if (!m.sources || !m.mappings) return;
  const base = sources.length;
  sources.push(...m.sources);
  const lines = m.mappings.split(";");
  let srcIdx = 0;
  const segsByLine = [];
  for (const line of lines) {
    const segs = line.split(",");
    let genCol = 0;
    const parsed = [];
    for (const seg of segs) {
      if (!seg) continue;
      const f = decodeVLQ(seg);
      genCol += f[0];
      if (f.length >= 4) srcIdx += f[1];
      parsed.push({ genCol, srcIdx });
    }
    segsByLine.push(parsed);
  }
  for (const segs of segsByLine) {
    for (let si = 0; si < segs.length; si++) {
      const start = segs[si].genCol;
      const end = si + 1 < segs.length ? segs[si + 1].genCol : Infinity;
      if (end === Infinity) continue; // last segment on a line has no end
      const w = Math.max(0, end - start);
      const gi = base + segs[si].srcIdx;
      if (gi >= 0 && gi < sources.length) perSource[gi] = (perSource[gi] || 0) + w;
    }
  }
}

const raw = JSON.parse(fs.readFileSync(process.argv[2], "utf8"));
const perSource = [];
const sources = [];
if (raw.sections) {
  for (const s of raw.sections) attribute(s.map, perSource, sources);
} else {
  attribute(raw, perSource, sources);
}
const rows = sources
  .map((s, i) => ({ src: s, gen: perSource[i] || 0 }))
  .filter((r) => r.gen > 0)
  .sort((a, b) => b.gen - a.gen);
const kb = (n) => (n / 1024).toFixed(1);
const TOP = parseInt(process.argv[4] ?? process.argv[3] ?? "25", 10);
console.log(`== ${process.argv[2]} == sources with mapped bytes: ${rows.length}`);
for (const r of rows.slice(0, TOP)) console.log(`${kb(r.gen)}kB  ${r.src}`);
const pk = new Map();
for (const r of rows) {
  const m = r.src.match(/node_modules\/((@[^/]+\/)?[^/]+)/);
  const key = m ? `node_modules/${m[1]}` : r.src.replace(/^.*\/(src|app)\//, "$1/");
  pk.set(key, (pk.get(key) || 0) + r.gen);
}
console.log("\n-- rollup by package --");
for (const [k, v] of [...pk.entries()].sort((a, b) => b[1] - a[1]).slice(0, 20))
  console.log(`${kb(v)}kB  ${k}`);
console.log(`mapped-total: ${kb(rows.reduce((a, r) => a + r.gen, 0))}kB`);
